sp_widget.client_script:
api.controller = function (spUtil) {
    var c = this

    c.refresh = function () {
        spUtil.update(c)
    }
}

sp_widget.css:
// Colours come from theme variables only - no raw hex values.
.x-car-my-reservations {
    .panel-title {
        font-size: 1.125rem;
        margin: 0;
        color: $text-color;
    }

    .x-car-table {
        margin-bottom: 0;

        th {
            color: $table-heading;
            white-space: nowrap;
        }

        td,
        th {
            vertical-align: middle;
        }
    }

    .x-car-actions {
        text-align: right;
        white-space: nowrap;
    }

    .panel-footer {
        background-color: $background-secondary;

        .btn + .btn {
            margin-left: 0.5rem;
        }
    }

    // Stack the table into cards on small screens.
    @media (max-width: 767px) {
        .x-car-table {
            thead {
                display: none;
            }

            tr {
                display: block;
                border-bottom: 1px solid $table-border-color;
                padding: 0.5rem 0;
            }

            td {
                display: block;
                border: 0;

                &::before {
                    content: attr(data-th) ': ';
                    font-weight: 700;
                    color: $text-muted;
                }
            }

            .x-car-actions {
                text-align: left;

                &::before {
                    content: '';
                }
            }
        }
    }
}

sp_widget.script:
;(function () {
    data.table = 'x_2203703_car_re_0_reservation'
    data.formPage = 'form'
    data.loggedIn = gs.isLoggedIn()
    data.reservations = []

    if (!data.loggedIn) {
        return
    }

    var stateClasses = {
        reserved: 'label-info',
        closed: 'label-success',
        cancelled: 'label-danger',
    }

    var gr = new GlideRecord(data.table)
    gr.addQuery('applicant', gs.getUserID())
    gr.orderByDesc('start_date')
    gr.setLimit(50)
    gr.query()

    while (gr.next()) {
        var state = gr.getValue('state') || ''
        data.reservations.push({
            sys_id: gr.getUniqueValue(),
            car: gr.getDisplayValue('car'),
            rental_duration: gr.getDisplayValue('rental_duration'),
            start_date: gr.getDisplayValue('start_date'),
            end_date: gr.getDisplayValue('end_date'),
            state: gr.getDisplayValue('state'),
            state_value: state,
            state_class: stateClasses[state] || 'label-default',
            driver_name: gr.getDisplayValue('driver_name'),
        })
    }

    data.count = data.reservations.length
})()
